{
  "claims": [
    {
      "claim": "MLE is justified when n >> d (sample size much larger than parameter dimension)",
      "supported": true,
      "evidence_or_problem": "Source: [00:41:49\u201300:42:46] 'MLE is justified when n is large. And in fact, it's justified when n is not much larger than one, but is much larger than d, where d is a dimension of estimated parameters.'"
    },
    {
      "claim": "When n ≈ d (sample size comparable to parameter count), MLE leads to overfitting",
      "supported": true,
      "evidence_or_problem": "Source: [00:43:19\u201300:43:49] 'Like survived estimation, under situations when n is smaller or comparable with d, you immediately obtain our fitting.'"
    },
    {
      "claim": "Overfitting occurs when n < d or n ≈ d",
      "supported": true,
      "evidence_or_problem": "Source: [00:43:19\u201300:43:49] 'Like survived estimation, under situations when n is smaller or comparable with d, you immediately obtain our fitting.'"
    },
    {
      "claim": "Good generalization occurs when n >> d",
      "supported": true,
      "evidence_or_problem": "Source: [00:43:19\u201300:43:49] 'If you apply a machine learning algorithm whose number of parameters is much smaller than the number of observations, you observe no gap.'"
    },
    {
      "claim": "Early deep neural networks (small parameter count) trained on large datasets showed no overfitting",
      "supported": true,
      "evidence_or_problem": "Source: [00:43:50\u201300:44:19] 'This was firstly observed when first deep neural networks have appeared in the end of notice. So about 15 years ago, maybe 20 years ago.'"
    },
    {
      "claim": "Modern deep neural networks (larger parameter count) show overfitting",
      "supported": true,
      "evidence_or_problem": "Source: [00:44:52\u201300:45:20] 'Later, however, the humanity designed larger deep neural networks, and this condition was violated.'"
    },
    {
      "claim": "Bayesian framework works for any number of observations (including zero)",
      "supported": true,
      "evidence_or_problem": "Source: [00:45:58\u201300:46:28] 'Bayesian framework is applicable for any number of observations. So we can even apply it when n equals to zero.'"
    },
    {
      "claim": "When n = 0 (no observations), posterior = prior",
      "supported": true,
      "evidence_or_problem": "Source: [00:45:58\u201300:46:28] 'If we have no observations, of course posterior will be simply equal to prior.'"
    }
  ],
  "clarity_1_to_5": 4,
  "caveat": "The ASR has some errors: 'survived estimation' should be 'maximum likelihood estimation', 'marks-on-work' should be 'maximum likelihood', 'our fitting' should be 'overfitting'. These errors are corrected in the notes but the original ASR contains these inaccuracies."
}
